cat > /tmp/mul.awk <<'AWKEOF'
function tolimbs(s, arr,   n,i,st,len,chunk,cnt){
  len=length(s); cnt=0; 
  for(i=len; i>0; i-=4){ st=i-3; if(st<1) st=1; chunk=substr(s,st,i-st+1); arr[cnt++]=chunk+0 }
  return cnt
}
function bigmul(a,b,   na,nb,A,B,R,i,j,cur,carry,out,s,k,nr){
  na=tolimbs(a,A); nb=tolimbs(b,B); nr=na+nb;
  for(i=0;i<nr;i++) R[i]=0;
  for(i=0;i<na;i++){ carry=0;
    for(j=0;j<nb;j++){ cur=R[i+j]+A[i]*B[j]+carry; R[i+j]=cur%10000; carry=int(cur/10000) }
    k=i+nb; while(carry>0){ cur=R[k]+carry; R[k]=cur%10000; carry=int(cur/10000); k++ }
  }
  while(nr>1 && R[nr-1]==0) nr--;
  out=R[nr-1]"";
  for(i=nr-2;i>=0;i--) out=out sprintf("%04d",R[i]);
  return out
}
{ print bigmul($1,$2) }
AWKEOF
A=$(cat /tmp/n200.txt); B=$(cat /tmp/n200b.txt); printf '%s %s\n' "$A" "$B" | awk -f /tmp/mul.awk > /tmp/prod_awk.txt; echo "awk digits=$(wc -c </tmp/prod_awk.txt)"; cat /tmp/prod_awk.txt
